from triage.pii.scrubber import Scrubber
s=Scrubber()

planted=collections.Counter(); detected=collections.Counter()
partial=collections.Counter(); misses=collections.defaultdict(list)

for line in open('data/generated/emails.jsonl',encoding='utf-8'):
    d=json.loads(line); pp=d.get('plant_pii') or {}
    if not isinstance(pp,dict): continue
    txt=(d.get('subject','') or '')+'\n'+(d.get('body','') or '')
    out=s.scrub(txt).text
    for typ,val in pp.items():
        if not val: continue
        val=str(val)
        if val not in txt:      # planted but never actually written into the email
            continue
        planted[typ]+=1
        if val.lower() not in out.lower():
            detected[typ]+=1
            # component check: did every meaningful token go too?
            toks=[t for t in re.split(r'[\s,#]+',val) if len(t)>2 and t.lower() not in ('blk','block')]
            surv=[t for t in toks if re.search(r'(?<![A-Za-z0-9])'+re.escape(t)+r'(?![A-Za-z0-9])',out,re.I)]
            if surv: partial[typ]+=1; misses[typ].append((val,surv))
